source(file.path(commandArgs(TRUE)[1],'code/common.R'));suppressPackageStartupMessages(library(spacexr));Sys.setenv(R_PROFILE_USER=file.path(root,'code/worker_profile.R'),OMP_NUM_THREADS="1",OPENBLAS_NUM_THREADS="1");if(file.exists(file.path(out,'rctd_summary.json')))quit(save='no');d<-fread(file.path(out,'bin_metadata.tsv.gz'),data.table=FALSE,na.strings=c('','NA'));roi<-d[!is.na(d$roi),];inc<-roi$qc_keep;info<-read_json(file.path(out,'input_summary.json'),simplifyVector=TRUE);q<-Read10X_h5(file.path(hd,info$matrix_path),use.names=FALSE);q<-q[,roi$bin_id[inc],drop=FALSE];coords<-data.frame(x=roi$x_um[inc],y=roi$y_um[inc],row.names=roi$bin_id[inc]);sp<-SpatialRNA(coords,q,colSums(q));r<-readRDS(file.path(major,'reference/reference.rds'));rc<-LayerData(r,assay='RNA',layer='counts');labs<-factor(gsub('/', '_',r$major,fixed=TRUE));names(labs)<-colnames(rc);ref<-Reference(rc,labs,nUMI=colSums(rc),n_max_cells=50000,min_UMI=100);refcounts<-data.table(major=as.character(ref@cell_types))[,.(n=.N),by=major];fwrite(refcounts,file.path(out,'rctd_reference_counts.tsv'),sep='\t');rm(r,rc);gc();fit<-create.RCTD(sp,ref,max_cores=4,UMI_min=100,UMI_min_sigma=300,counts_MIN=10,keep_reference=FALSE);input_ids<-colnames(fit@spatialRNA@counts);write_json(fit@config,file.path(out,'rctd_config.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA);fit<-run.RCTD(fit,doublet_mode='doublet');res<-as.data.frame(fit@results$results_df);res$bin_id<-rownames(res);for(k in intersect(c('first_type','second_type'),names(res))){res[[k]]<-as.character(res[[k]]);res[[k]][res[[k]]=='T_NK']<-'T/NK'};w<-as.data.frame(fit@results$weights_doublet);names(w)<-paste0('weight_',seq_len(ncol(w)));w$bin_id<-rownames(w);res<-merge(res,w,by='bin_id',all=TRUE,sort=FALSE);fwrite(res,file.path(out,'rctd_fitted.tsv.gz'),sep='\t')
rt<-roi[,c('bin_id','roi','nCount_RNA','nFeature_RNA','qc_keep','x_um','y_um')];rt$rctd_status<-ifelse(!rt$qc_keep,'not_in_bin_QC',ifelse(rt$nCount_RNA<100,'below_UMI_min100','excluded_other_algorithm_gate'));j<-match(rt$bin_id,res$bin_id);ok<-!is.na(j);for(k in setdiff(names(res),'bin_id'))rt[[k]]<-res[[k]][j];rt$rctd_status[ok]<-as.character(res$spot_class[j[ok]]);fwrite(rt,file.path(out,'rctd_ROI_results.tsv.gz'),sep='\t');writeLines(capture.output(str(fit@results[c('results_df','weights_doublet')],max.level=2)),file.path(out,'rctd_output_structure.txt'));summary<-list(section=s,version=as.character(packageVersion('spacexr')),mode='doublet',model_limit='fits one or two dominant types; not a maximum true cell count',reference_input=44896,reference_retained=ncol(ref@counts),ROI_bins=nrow(roi),ROI_UMI=sum(roi$nCount_RNA),ROI_QC_bins=sum(inc),fitted_bins=sum(ok),fitted_UMI=sum(rt$nCount_RNA[ok]),UMI_min=100,counts_MIN=10,UMI_min_sigma=300,statuses=as.list(table(rt$rctd_status)),ROI_outside='not_tested',projected=FALSE);write_json(summary,file.path(out,'rctd_summary.json'),auto_unbox=TRUE,pretty=TRUE);cat('RCTD_COMPLETE',s,'\n')
